#!/usr/bin/env node
// Summarize a JSONL event log: counts per level, plus the time range.

import { readFileSync } from "node:fs";

export function summarize(text, { since } = {}) {
  let sinceMs;
  if (since !== undefined) {
    sinceMs = Date.parse(since);
    if (Number.isNaN(sinceMs)) throw new RangeError(`invalid --since date: ${since}`);
  }
  const levels = {};
  const times = [];
  for (const line of text.split(/\r?\n/)) {
    if (!line.trim()) continue;
    const event = JSON.parse(line);
    if (sinceMs !== undefined) {
      const eventMs = Date.parse(event.time);
      if (Number.isNaN(eventMs) || eventMs < sinceMs) continue;
    }
    levels[event.level] = (levels[event.level] ?? 0) + 1;
    if (event.time) times.push(event.time);
  }
  times.sort();
  return { levels, first: times[0] ?? null, last: times[times.length - 1] ?? null };
}

if (import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  const flag = "--since";
  const flagEq = flag + "=";
  const args = process.argv.slice(2);
  const positional = [];
  let since;
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === flag) {
      since = args[++i] ?? "";
    } else if (arg.startsWith(flagEq)) {
      since = arg.slice(flagEq.length);
    } else {
      positional.push(arg);
    }
  }
  const file = positional[0] ?? "fixtures/events.jsonl";
  let summary;
  try {
    summary = summarize(readFileSync(file, "utf8"), { since });
  } catch (error) {
    if (!(error instanceof RangeError)) throw error;
    console.error(`log-summary: ${error.message}`);
    process.exit(1);
  }
  console.log(JSON.stringify(summary, null, 2));
}

